css:
.brutalist-button {
  display: flex;
  align-items: center;
  width: 250px;
  height: 80px;
  background-color: #000000;
  color: #000;
  text-decoration: none;
  border: 4px solid #000;
  outline: 4px solid #f7f5f5;
  box-shadow: 8px 8px 0 #000000;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  padding: 0 16px;
  box-sizing: border-box;
  position: relative;
  overflow: hidden;
}

.brutalist-button::before {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    45deg,
    transparent,
    rgba(255, 255, 255, 0.8),
    transparent
  );
  transform: rotate(45deg);
  transition: 0.5s;
  opacity: 0;
}

.brutalist-button:hover::before {
  animation: glare 1.5s infinite;
}

@keyframes glare {
  0% {
    transform: rotate(45deg) translateY(-100%);
    opacity: 0;
  }
  50% {
    transform: rotate(45deg) translateY(100%);
    opacity: 1;
  }
  100% {
    transform: rotate(45deg) translateY(100%);
    opacity: 0;
  }
}

.brutalist-button:hover {
  transform: translate(-4px, -4px);
  box-shadow: 12px 12px 0 #ff4500;
  background-color: #000;
  color: #f0f0f0;
  outline-color: #000;
}

.brutalist-button:active {
  transform: translate(4px, 4px);
  box-shadow: 0px 0px 0 #ff4500;
  transition: all 0.1s cubic-bezier(0.25, 0.8, 0.25, 1);
}

.ms-logo {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 3px;
  width: 40px;
  height: 40px;
  margin-right: 16px;
  flex-shrink: 0;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  position: relative;
  z-index: 2;
  transform: rotate(0deg);
}

.brutalist-button:hover .ms-logo {
  animation: logoSpin 0.5s cubic-bezier(0.25, 0.8, 0.25, 1);
}

@keyframes logoSpin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

.ms-logo-square {
  width: 100%;
  height: 100%;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

.ms-logo-square:nth-child(1) {
  background-color: #f25022;
}
.ms-logo-square:nth-child(2) {
  background-color: #7fba00;
}
.ms-logo-square:nth-child(3) {
  background-color: #00a4ef;
}
.ms-logo-square:nth-child(4) {
  background-color: #ffb900;
}

.brutalist-button:hover .ms-logo-square:nth-child(odd) {
  transform: scale(1.2);
}

.brutalist-button:hover .ms-logo-square:nth-child(even) {
  transform: scale(0.8);
}

.button-text {
  display: flex;
  flex-direction: column;
  line-height: 1;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  position: relative;
  z-index: 2;
}

.brutalist-button:hover .button-text {
  transform: skew(-5deg);
}

.button-text span:first-child {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: bold;
  color: #ffffff;
}

.button-text span:last-child {
  font-size: 17px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #ffffff;
}

.brutalist-button:hover .button-text span:first-child {
  color: #00a4ef;
}

.brutalist-button::after {
  content: "►";
  position: absolute;
  right: -30px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 24px;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

.brutalist-button:hover::after {
  right: 16px;
}
